llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Trametinib, a pyridopyrimidinone-based oral kinase inhibitor, has a mean absolute bioavailability of 72% after a 2 mg oral dose in humans, supporting high F for the similarly pyridopyrimidinone-containing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Niraparib has an absolute oral bioavailability of approximately 73% in humans after a 300 mg dose, supporting high F for a small-molecule oral kinase inhibitor with moderate structural similarity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Imatinib has a mean absolute bioavailability of 98% in humans and shares the piperazine-anilinopyrimidine motif with the query, supporting high oral F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Brigatinib, an oral kinase inhibitor with an anilinopyrimidine and piperazine-containing structure, has an estimated oral bioavailability of 46% in healthy volunteers, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Brepocitinib has an estimated absolute bioavailability of 75% in humans, supporting high oral F for a small-molecule kinase inhibitor with moderate structural overlap.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Risdiplam has high oral bioavailability in humans due to almost complete absorption and negligible first-pass effects, supporting high F for a heteroaromatic oral drug with some shared piperazine/pyridinone features.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Transferable human absolute bioavailability evidence from structurally related oral kinase inhibitors consistently supports F ≥ 20%; no affirmative low-bioavailability evidence transfers to the query.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule is provided.",
    "The only record with a low bioavailability tail (mCPP, 12–84%) is structurally unrelated and highly variable, so it does not affirmatively support low F for the query.",
    "Exact human pharmacokinetic conditions for the query, such as dose, formulation, and fed/fasted state, are not supplied."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

